$TP$ is tangent to a circle with centre $O$ at $T$. Given $\angle TOP=62^{\circ}$, find $x=\angle OPT$.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (O) at (0,0); \coordinate (T) at (0,2); \coordinate (P) at ({2*tan(62)},2);
\draw (O) circle (2); \draw (O)--(T)--(P)--cycle;
\fill (O) circle (1.5pt);
\path (O) node[below left] {$O$} (T) node[above] {$T$} (P) node[right] {$P$};
\path (0.35,0.8) node {$62^{\circ}$} ({2*tan(62)-0.8},1.8) node {$x$};
\end{tikzpicture}
[/tikz]

$PA$ and $PB$ are tangents from the external point $P$. Given $PA=8.4\text{ cm}$, find $PB$.
[tikz]
\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (A) at (1,{sqrt(3)}); \coordinate (B) at (1,{-sqrt(3)}); \coordinate (P) at (4,0);
\draw (0,0) circle (2); \draw (A)--(P)--(B);
\path (A) node[above] {$A$} (B) node[below] {$B$} (P) node[right] {$P$};
\path (2.5,0.866) node[above right] {$8.4\text{ cm}$};
\end{tikzpicture}
[/tikz]

$PT$ and $PQ$ are tangents to the circle. Given $\angle TPQ=60^{\circ}$, find $x=\angle PTQ$.
[tikz]
\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (T) at (1,{sqrt(3)}); \coordinate (Q) at (1,{-sqrt(3)}); \coordinate (P) at (4,0);
\draw (0,0) circle (2); \draw (T)--(P)--(Q)--cycle;
\path (T) node[above] {$T$} (Q) node[below] {$Q$} (P) node[right] {$P$};
\path (3.1,0) node {$60^{\circ}$} (1.35,1.1) node {$x$};
\end{tikzpicture}
[/tikz]

$PT$ and $PQ$ are tangents to a circle with centre $O$. The smaller angle $\angle TOQ=120^{\circ}$. Find $\angle TPQ$.
[tikz]
\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (O) at (0,0); \coordinate (T) at (1,{sqrt(3)}); \coordinate (Q) at (1,{-sqrt(3)}); \coordinate (P) at (4,0);
\draw (O) circle (2); \draw (O)--(T)--(P)--(Q)--cycle; \fill (O) circle (1.5pt);
\path (O) node[left] {$O$} (T) node[above] {$T$} (Q) node[below] {$Q$} (P) node[right] {$P$};
\draw (0.65,-1.126) arc[start angle=-60,end angle=60,radius=1.3];
\path (0.7,0) node {$120^{\circ}$};
\end{tikzpicture}
[/tikz]

$PT$ and $PQ$ are tangents to a circle with centre $O$. The reflex angle $\angle TOQ=240^{\circ}$. Find $\angle TPQ$.
[tikz]
\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (O) at (0,0); \coordinate (T) at (1,{sqrt(3)}); \coordinate (Q) at (1,{-sqrt(3)}); \coordinate (P) at (4,0);
\draw (O) circle (2); \draw (O)--(T)--(P)--(Q)--cycle; \fill (O) circle (1.5pt);
\path (O) node[below right] {$O$} (T) node[above] {$T$} (Q) node[below] {$Q$} (P) node[right] {$P$};
\draw (0.45,0.7794) arc[start angle=60,end angle=300,radius=0.9];
\path (-1.1,0) node {$240^{\circ}$};
\end{tikzpicture}
[/tikz]

$TP$ is tangent to a circle with centre $O$ at $T$.

(a) Given $OT=7\text{ cm}$ and $TP=24\text{ cm}$, find $OP$.

(b) In another circle, the diameter is $14\text{ cm}$ and $OP=25\text{ cm}$. Find $TP$.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (O) at (0,0); \coordinate (T) at (0,1.4); \coordinate (P) at (4.8,1.4);
\draw (O) circle (1.4); \draw (O)--(T)--(P)--cycle; \fill (O) circle (1.5pt);
\path (O) node[below left] {$O$} (T) node[above] {$T$} (P) node[right] {$P$};
\end{tikzpicture}
[/tikz]

$PA$ and $PB$ are tangents to a circle with centre $C$. Prove that $\triangle PAC\equiv\triangle PBC$, and hence that $PA=PB$.
[tikz]
\begin{tikzpicture}[x=9mm,y=9mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (C) at (0,0); \coordinate (A) at (1,{sqrt(3)}); \coordinate (B) at (1,{-sqrt(3)}); \coordinate (P) at (4,0);
\draw (C) circle (2); \draw (C)--(A)--(P)--(B)--cycle; \draw (C)--(P); \fill (C) circle (1.5pt);
\path (C) node[left] {$C$} (A) node[above] {$A$} (B) node[below] {$B$} (P) node[right] {$P$};
\end{tikzpicture}
[/tikz]

The incircle of $\triangle PQR$ touches $PQ$ at $X$, $QR$ at $Y$, and $RP$ at $Z$. Given $PQ=10\text{ cm}$, $QR=12\text{ cm}$ and $RP=14\text{ cm}$, find $QY$ using three simultaneous equations.
[tikz]
\begin{tikzpicture}[x=8mm,y=8mm,every node/.style={font=\fontsize{10}{12}\selectfont},draw=black,text=black]
\coordinate (Q) at (0,0); \coordinate (R) at (6,0); \coordinate (P) at (1,{sqrt(24)});
\coordinate (I) at (2,{sqrt(24)/3}); \coordinate (X) at (0.4,{0.4*sqrt(24)}); \coordinate (Y) at (2,0); \coordinate (Z) at ({22/7},{4*sqrt(24)/7});
\draw (P)--(Q)--(R)--cycle; \draw (I) circle ({sqrt(24)/3});
\path (P) node[above] {$P$} (Q) node[below left] {$Q$} (R) node[below right] {$R$} (X) node[left] {$X$} (Y) node[below] {$Y$} (Z) node[right] {$Z$};
\end{tikzpicture}
[/tikz]
